    [1182] = { n = "Lil' Donkey", s = "|cFFFFD200Drop: |rOverseer Krix|n|cFFFFD200Zone: |rArathi Highlands", d = "Likely stolen from Newstead in the Arathi Highlands, this stalwart little donkey was destined to be eaten by kobolds." },
