    [1297] = { n = "Clutch of Ha-Li", s = "|cFFFFD200Drop: |rHa-Li|n|cFFFFD200Zone: |rVale of Eternal Blossoms", d = "The brood of Ha-Li are comfortable in the blue skies of Pandaria, hunting unsuspecting prey." },
    [1298] = { n = "Hopecrusher Gargon", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "Once the loyal mount of a House Briarbane lord, it turned on the lord and his retinue. Members of House Briarbane now whisper of a dark Gargon lying in wait even baiting venthyr who venture through the darker parts of the Chalice District of Revendreth." },
    [1299] = { n = "Battle Gargon Vrednic", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "Prince Renathal's loyal gargon, Vrednic has been by his side for millennia. Adorned in his Sinvyr armor, Vrednic's mere presence instills terror to all those who lay eyes on him as he ushers his rider into battle." },
    [1302] = { n = "Dreamlight Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "Runestags are granted to those who have pledged their service to the Winter Queen and the Court of Night." },
    [1303] = { n = "Enchanted Dreamlight Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "The majestic runestags are capable of siphoning anima from the ambient light of Ardenweald with their elaborate antlers. The anima is used as nourishment and to power the runestag's speed and magic." },
    [1304] = { n = "Mawsworn Soulhunter", s = "|cFFFFD200Drop: |rGorged Shadehound|n|cFFFFD200Zone: |rThe Maw", d = "Soulhunters are used to track wayward souls across the wastes that flee from their dark fates, and are one of the only creatures that feel comfortable traversing the maw." },
    [1305] = { n = "Darkwarren Hardshell", s = "|cFFFFD200Adventures:|r Shadowlands", d = "The Darkwarren Hardshell's chitin is sturdy enough to withstand mortar shells and dragon's fire. It will also conveniently consume anything lacking anima, if needed." },
    [1306] = { n = "Swift Gloomhoof", s = "|cFFFFD200Drop: |rNight Mare|n|cFFFFD200Zone: |rArdenweald", d = "The ballads of Ardenweald claim that the birth of gloomrunner heralds the passing of a particularly benevolent wild god. Seeing a gloomrunner is therefore a blessing and a curse." },
    [1307] = { n = "Sundancer", s = "|cFFFFD200Drop:|r Sundancer|n|cFFFFD200Zone:|r Bastion|n", d = "This sun-dappled courser gallops on lightbeams with carefree abandon." },
    [1309] = { n = "Chittering Animite", s = "|cFFFFD200Adventures:|r Shadowlands|n", d = "These exceptionally agile fliers make excellent mounts once they've been trained not to sap every ounce of anima from their rider." },
    [1310] = { n = "Horrid Dredwing", s = "|cFFFFD200Drop: |rHarika the Horrid|n|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "Harika the Horrid terrorized the denizens of the Forest Ward, and with her demise her broodlings can now take this horror to denizens farther afield." },
    [1311] = { n = "Ivory Cloud Serpent", s = "|cFFFFD200Drop:|r Ivory Cloud Serpent|n|cFFFFD200Zone:|r Vale of Eternal Blossoms", d = "Ivory Cloud Serpents are often mistaken for roaring thunder as they tear through the skies with blistering speed." },
    [1312] = { n = "Gargantuan Grrloc" },
    [1313] = { n = "Rajani Warserpent" },
    [1314] = { n = "Drake of the Four Winds", s = "|cFFFFD200Drop: |rIshak of the Four Winds|n|cFFFFD200Zone: |rUldum", d = "Rocks erode, fires sputter, but wind remains powerful regardless of the passage of time. -Phaoris" },
    [1315] = { n = "Mail Muncher", s = "|cFFFFD200Drop: |rMail Muncher|n|cFFFFD200Zone: |rHorrific Visions", d = "Worming its way through the Postmaster's network, this serpent of N'Zoth deprived Azeroth of its primary magical correspondence." },
    [1317] = { n = "Waste Marauder", s = "|cFFFFD200Drop: |rRotfeaster|n|cFFFFD200Zone: |rUldum", d = "Larger than most of its kin, this vulture has shown sick and strong beasts alike why they need to fear the skies." },
    [1318] = { n = "Wastewander Skyterror" },
    [1319] = { n = "Malevolent Drone", s = "|cFFFFD200Drop:|r Corpse Eater|n|cFFFFD200Zone: |rUldum", d = "The Aqir drones feast on heroes and cowards alike to grow their ranks." },
    [1320] = { n = "Shadowbarb Drone", s = "|cFFFFD200Quest: |rMy Own Drone|n|cFFFFD200Zone: |rUldum", d = "Void, jelly, and a very full belly is all this drone needs." },
