    [1324] = { n = "Elusive Quickhoof" },
    [1326] = { n = "Awakened Mindborer" },
    [1327] = { n = "Ren's Stalwart Hound", s = "|cFFFFD200Drop: |rHoundlord Ren|n|cFFFFD200Zone: |rVale of Eternal Blossoms", d = "Houndlord Ren used his strongest quilen to carry him across Pandaria to subjugate the Vale for the Mogu empire." },
    [1328] = { n = "Xinlao", s = "|cFFFFD200Drop: |rAnh-De the Loyal|n|cFFFFD200Zone: |rVale of Eternal Blossoms", d = "The only thing stronger than a quilen's loyalty is its fierce devotion to making sure it covers its owner in kisses." },
    [1329] = { n = "Springfur Alpaca", s = "|cFFFFD200Quest: |rAlpaca It In|n|cFFFFD200Zone: |rUldum", d = "The kind nature of alpacas makes them perfect as companions for the intrepid adventurer." },
