    [1350] = { n = "Colossal Slaughterclaw", s = "|cFFFFD200Drop: |rSupplies of the Undying Army|n|cFFFFD200Zone: |rMaldraxxus", d = "Only the most stalwart stable masters of Maldraxxus are able to break the will of the colossal slaughterclaws, giving all champions of the Undying Army a fearsome ally in the Shadowlands." },
    [1351] = { n = "Vicious War Spider" },
    [1352] = { n = "Vicious War Spider" },
    [1354] = { n = "Shadeleaf Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "The shadeleaf runestag are bred for their ferocity as well as their beauty by the Wild Hunt. They feel no fear charging into the den of any predator." },
    [1355] = { n = "Wakener's Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "Runestags enjoy lying near wildseeds. The Wakeners believe they can hear the sleepers' dreams. These runestags display a range of emotions in their vigil, signaling the dreams or nightmares of the spirits within." },
    [1356] = { n = "Winterborn Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "Winterborn runestags are blessed by the Winter Queen herself. Their runes flare brilliantly when predators are nearby, warning the entire herd." },
    [1357] = { n = "Enchanted Shadeleaf Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "A shadeleaf runestag is capable of goring creatures as powerful as a gorm matriarch in defense of its herd. The Wild Hunt ride these mounts into dangerous corners of the Shadowlands, when their domain must be defended from those who would threaten the wilds." },
    [1358] = { n = "Enchanted Wakener's Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "Wakener runestags fiercely protect their wildseed groves. When the groves starting to fail, many runestags went berserk." },
    [1359] = { n = "Enchanted Winterborn Runestag", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "Winterborn runestags are the favored mount of the Winter Queen herself, and she only bestows such a creature on her most favored subjects." },
    [1360] = { n = "Shimmermist Runner", s = "|cFFFFD200Area: |rMistveil Tangle|n|cFFFFD200Zone: |rArdenweald", d = "Mischievous spriggans and the valerunners have a natural enmity. No valerunner would deign to allow a spriggan rider because they can sense their inherent malevolence. This angers the trickster spriggans who take twisted enjoyment in playing cruel pranks on these majestic creatures." },
    [1361] = { n = "Duskflutter Ardenmoth" },
    [1362] = { n = "Spinemaw Gladechewer", s = "|cFFFFD200Drop: |rGormtamer Tizo|n|cFFFFD200Zone: |rArdenweald", d = "Spriggan riders tie bits of anima-less detritus to the end of sticks in front of their gorm mounts to steer. It's... an imperfect art." },
    [1363] = { n = "Sinful Gladiator's Soul Eater" },
    [1364] = { n = "War-Bred Tauralus", s = "|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "The soldiers of Maldraxxus protect the Shadowlands, and require a mount that is both capable and calm when faced with overwhelming odds." },
    [1365] = { n = "Plaguerot Tauralus", s = "|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "The tauralus is considered courageous, though scholars of Maldraxxus have long wondered if their lack of fear is simply due to the tiny size of their brains." },
    [1366] = { n = "Bonehoof Tauralus", s = "|cFFFFD200Drop: |rTahonta|n|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "There are quite a few reasons that you do not want to stand behind a tauralus, the hooves and whip-like tails being the least of them." },
    [1367] = { n = "Chosen Tauralus" },
    [1368] = { n = "Armored War-Bred Tauralus", s = "|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "The tauralus that serve the armies of Maldraxxus have had all traits of compassion bred out of them, and are only adorned in armor when they show that no sword or spell can stop them from carrying their rider to victory." },
    [1369] = { n = "Armored Plaguerot Tauralus" },
    [1370] = { n = "Armored Bonehoof Tauralus", s = "|cFFFFD200Drop: |rSabriel the Bonecleaver|n|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "A favored mount of the House of the Chosen, the tauralus only gets more angry and vicious when exposed to battle." },
    [1371] = { n = "Armored Chosen Tauralus" },
    [1372] = { n = "Blisterback Bloodtusk", s = "|cFFFFD200Drop:|r Warbringer Mal'korak|n|cFFFFD200Zone: |rMaldraxxus", d = "The House of the Chosen train their mounts in all manner of difficult circumstances, so that no matter the battle, they will never falter." },
    [1373] = { n = "Gorespine", s = "|cFFFFD200Drop: |rNerissa Heartless|n|cFFFFD200Zone: |rMaldraxxus", d = "Nerissa trampled over countless bodies on the back of Gorespine as she rose to prominence as the commander of the Lichsworn forces for the House of Rituals." },
    [1374] = { n = "Bonecleaver's Skullboar", s = "|cFFFFD200Vendor:|r Collector Ta'Steld|n|cFFFFD200Zone:|r Oribos|n|cFFFFD200Cost: |r5000|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h|n|n", d = "Sabreil was known for the ruthless efficiency with which she dismembered foes, feeding their bones to her loyal skullboar." },
    [1375] = { n = "Lurid Bloodtusk" },
    [1376] = { n = "Silvertip Dredwing" },
    [1377] = { n = "Rampart Screecher" },
    [1378] = { n = "Harvester's Dredwing", s = "|cFFFFD200Drop:|r Harvester's War Chest|n|cFFFFD200Zone:|r The Maw ", d = "The dredwings of the Harvesters fear no mawsworn, and will gleefully sink their teeth into anything that threatens Sinfall." },
    [1379] = { n = "Endmire Flyer", s = "|cFFFFD200Drop: |rFamu the Infinite|n|cFFFFD200Zone: |rRevendreth", d = "Attracted through portals through which little is known these flying devourers have found a home in the Endmire of Revendreth feeding on the latent anima." },
    [1382] = { n = "Inquisition Gargon", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "The gargon of the Inquisitors are some of the most vicious ever carved. The Avowed seek to recapture these beasts and return them to the righteous duty of assisting in the purifying of souls rather than the perversions performed at the hands of the Inquisitors." },
    [1384] = { n = "Sinfall Gargon", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "The gargon are the loyal mounts and companions of the Venthyr and Renathal has found many abandoned at Sinfall, awaiting reawakening and assignment to worthy members of the covenant." },
    [1385] = { n = "Crypt Gargon" },
    [1387] = { n = "Desire's Battle Gargon", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "The Countess maintains a small stable of elegantly adorned gargon mounts for her sole use. Many a rival has been taken in by the finery to their peril as she personally oversees their deadly training." },
    [1388] = { n = "Gravestone Battle Gargon", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "Representative of a new loyal batch of gargon, these battle ready beasts will take Renathal's most loyal compatriots into the final battles against the Jailer." },
    [1389] = { n = "Battle Gargon Silessa", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "Silessa fought valiantly alongside her master in the great incursion by the Light, following the battle her master set her to guard over a vault room of great value." },
    [1391] = { n = "Loyal Gorger", s = "|cFFFFD200Quest: |rA New Pack", d = "Crawling forth from the cracks between the realms, the devourers have a voracious appetite for anima. Little is known of their origins, but all denizens of the Shadowlands see their recent boldness as a sign of the end times." },
    [1442] = { n = "Corridor Creeper" },
    [1392] = { n = "Pale Acidmaw" },
    [1393] = { n = "Wild Glimmerfur Prowler", s = "|cFFFFD200Drop: |rValfir the Unrelenting|n|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "This prowler's brilliant green coat distinguishes it from the blues and purples of Ardenweald, making it much easier for others of its kind to see through the midnight woods." },
    [1394] = { n = "Phalynx of Loyalty", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "Some within the Ascended keep a phalynx as a pet. While they may not be as furry as a larion, they are much less likely to eat your other pets." },
    [1395] = { n = "Phalynx of Humility", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "The phalynx does not fetch, though it is not known why this is." },
    [1396] = { n = "Phalynx of Courage", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "A phalynx is considered both a worthy companion and a lithe opponent to test one's reflexes against." },
    [1397] = { n = "Wildseed Cradle", s = "|cFFFFD200Treasure: |rCache of the Moon|n|cFFFFD200Zone: |rArdenweald", d = "The most precious cargo in all Ardenweald, the wildseeds, are cradled by this lovingly-crafted cart. It is imbued with anima to allow it to hover over the ground." },
    [1398] = { n = "Phalynx of Purity", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "Little is known about the origination of phalynx technology, the machinations of which are taught more akin to religion than engineering." },
    [1399] = { n = "Eternal Phalynx of Purity", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "The armored phalynx is a favorite companion of the mightiest warriors of the Ascended as it is both fearless and vicious in battle." },
    [1400] = { n = "Eternal Phalynx of Courage", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "Many bars of gildenite are required to forge one of these sparkling mounts, but the sight of them alone is worth the gathering time." },
    [1401] = { n = "Eternal Phalynx of Loyalty", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "A marvel of steward engineering, the armored phalynx is a rare and awe-inspiring sight." },
    [1402] = { n = "Eternal Phalynx of Humility", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "When an armored phalynx is forged, stewards clap their hammers together in reverence of the skill required in its creation." },
    [1404] = { n = "Silverwind Larion", s = "|cFFFFD200Treasure: |rGift of the Silver Wind|n|cFFFFD200Zone: |rBastion", d = "This gift of the silvery winds is only bestowed upon those that search high and low for the wisdom of Bastion." },
    [1405] = { n = "Restoration Deathwalker" },
    [1406] = { n = "Marrowfang", s = "|cFFFFD200Drop:|r Nalthor the Rimebinder|n|cFFFFD200Zone: |rThe Necrotic Wake (Mythic)|n|n|cFFFFD200Drop:|r Challenger's Cache|n|cFFFFD200Zone: |rThe Necrotic Wake", d = "Marrowfang, Bonefang's progeny, was respected by Amarth the Harvester for her insatiable appetite, even if it disrupted any experiments that the sadistic commander wanted to run." },
    [1407] = { n = "Callow Flayedwing", s = "|cFFFFD200Zone: |rMaldraxxus", d = "Flayedwings are a necessary force in the cycle of life for the Shadowlands, acting as both prey and predator for the harsh environment of Maldraxxus." },
    [1408] = { n = "Gruesome Flayedwing" },
    [1409] = { n = "Bonesewn Fleshroc" },
    [1410] = { n = "Hulking Deathroc", s = "|cFFFFD200Drop: |rViolet Mistake|n|cFFFFD200Zone: |rMaldraxxus", d = "Deathrocs are stitched monstrosities from the discarded viscera, bone, and organs that were not required to construct soldiers for the House of Constructs." },
    [1411] = { n = "Predatory Plagueroc", s = "|cFFFFD200Drop: |rGieger|n|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "Gieger's everlasting hunger is legendary amongst the House of Constructs, and no beast is too large or bony to fit inside its massive stomach." },
    [1413] = { n = "Dauntless Duskrunner" },
    [1443] = { n = "Voracious Gorger" },
    [1414] = { n = "Sinrunner Blanchy", s = "|cFFFFD200NPC:|r Dead Blanchy |n|cFFFFD200Location:|r Revendreth|n |n", d = "In life, Blanchy appeared to be an affectionate, well-behaved horse of excellent disposition and appetite. What evils must she have committed in secret to have earned her place among the condemned souls of Revendreth?" },
    [1415] = { n = "Arboreal Gulper", s = "|cFFFFD200Drop: |rHumon'gozz|n|cFFFFD200Zone: |rArdenweald", d = "The wood and foliage growing atop this toad is a natural part of its body, helping it siphon anima from the air to nourish itself." },
    [1416] = { n = "Mawsworn Charger" },
    [1417] = { n = "Hand of Hrestimorak", s = "|cFFFFD200Achievement:|r Glory of the Dominant Raider|n|cFFFFD200Zone:|r Sanctum of Domination", d = "The treachery of Hrestimorak was infamous, betraying his people to claim power. Facing damnation in the Maw, he tried to subvert the Jailer... a foolish act that would earn him an eternity of torment." },
    [1419] = { n = "Sintouched Deathwalker" },
    [1420] = { n = "Umbral Scythehorn" },
    [1421] = { n = "Court Sinrunner" },
    [1422] = { n = "Warstitched Darkhound", s = "|cFFFFD200Adventures:|r Shadowlands", d = "These warhounds are crafted by the House of Constructs to carry any rider into the thick of battle, rending and tearing enemy mounts all the while." },
    [1423] = { n = "Highwind Darkmane", s = "|cFFFFD200Adventures:|r Shadowlands", d = "The Forsworn and their mounts take on a darker aspect upon renouncing the path laid forth by the Archon. While tame enough to ride, the Highwind Darkmane has a fiercely independent streak." },
    [1424] = { n = "Snowstorm" },
    [1425] = { n = "Gilded Prowler" },
    [1426] = { n = "Ascended Skymane", s = "|cFFFFD200Treasure: |rCache of the Ascended|n|cFFFFD200Zone: |rBastion", d = "Only those that have proven themselves against the combined might of the Ascended will be able to ride this mount." },
    [1428] = { n = "Amber Ardenmoth", s = "|cFFFFD200Drop:|r Wild Hunt Supplies|n|cFFFFD200Zone:|r Ardenweald|n", d = "The brilliant orange hue of the amber ardenmoth signals to predators that it is dangerous to eat. Consuming one of these creatures will put a predator into a dreamless sleep for years." },
    [1429] = { n = "Vibrant Flutterwing" },
    [1430] = { n = "Desertwing Hunter" },
    [1431] = { n = "Pale Regal Cervid" },
    [1433] = { n = "Vespoid Flutterer" },
    [1434] = { n = "Deepstar Aurelid", s = "|cFFFFD200Drop:|r Hirukon|n|cFFFFD200Zone:|r Zereth Mortis", d = "As one of the last remaining polyps of an elusive creature, this aurelid is at home in the water as much as the air." },
    [1436] = { n = "Battle-Hardened Aquilon" },
    [1437] = { n = "Battle-Bound Warhound", s = "|cFFFFD200Drop: |rTheater of Pain|n|cFFFFD200Zone: |rMaldraxxus", d = "Warhounds find comfort in conflict, and the Contest of Conquest is the perfect place to find these beasts honing their abilities." },
    [1438] = { n = "Bulbous Necroray", s = "|cFFFFD200Drop:|r Oozing Necroray Egg|n", d = "The necrorays of Maldraxxus prefer to congregate around the enormous decaying mushrooms of the region." },
    [1439] = { n = "Infested Necroray", s = "|cFFFFD200Drop:|r Oozing Necroray Egg|n", d = "Necrorays lay their eggs in small clusters within the frills and hollows of decaying fungal blooms." },
    [1440] = { n = "Pestilent Necroray", s = "|cFFFFD200Drop:|r Oozing Necroray Egg|n", d = "When a necroray hatches, spores fly everywhere, making a huge mess." },
    [1441] = { n = "Bound Shadehound", s = "|cFFFFD200Quest:|r Feral Shadehound|n|cFFFFD200Zone: |rThe Maw", d = "Created by deciphering and performing powerful runic magic, this Shadehound is bound to its creator." },
    [1444] = { n = "Viridian Phase-Hunter" },
    [1445] = { n = "Slime Serpent", s = "|cFFFFD200Drop: |rSlime Serpent|n|cFFFFD200Zone: |rPlaguefall", d = "This mysterious creature lurks beneath the slime pools of Plaguefall. No one knows where it came from." },
    [1446] = { n = "Tazavesh Gearglider" },
    [1448] = { n = "Serenade", s = "|cFFFFD200Profession: |rProtoform Synthesis", d = "These beautiful helicids emerge only at night. When they are pleased, their shells hum with a joyful melody." },
    [1449] = { n = "Lord of the Corpseflies", s = "|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Drop:|r Fleshwing|n|cFFFFD200Zone:|r Korthia ", d = "To be the Lord of the Corpseflies, you've got to lay a LOT of eggs." },
    [1450] = { n = "Soaring Razorwing" },
    [1451] = { n = "Vicious War Croaker", s = "|cFFFFD200PvP:|r Shadowlands: Season 3|nRated Arena and Rated Battleground Season Reward", d = "These creatures are so enthusiastic when charging into battle that they will croak out something that sounds very much like \"FOR THE HORDE!\"" },
    [1452] = { n = "Vicious War Croaker", s = "|cFFFFD200PvP:|r Shadowlands: Season 3|nRated Arena and Rated Battleground Season Reward", d = "These creatures are so enthusiastic when charging into battle that they will croak out something that sounds very much like \"FOR THE ALLIANCE!\"" },
    [1454] = { n = "Tamed Mauler", s = "|cFFFFD200Drop:|r Supplies of the Archivist's Codex|n|cFFFFD200Zone:|r Korthia |n", d = "When it comes to taming devourers, all it takes is a little anima and a lot of patience. And a lot of healing potions." },
    [1455] = { n = "Beryl Shardhide", s = "|cFFFFD200Drop:|r Death's Advance Supplies|n|cFFFFD200Zone:|r Korthia", d = "These shardhides find it easy to hide in the underbrush, and it is rare to find one that is tamed." },
    [1456] = { n = "Sapphire Skyblazer" },
    [1458] = { n = "Wandering Ancient" },
    [1459] = { n = "Vicious War Gorm" },
    [1460] = { n = "Vicious War Gorm" },
    [1465] = { n = "Vicious Warstalker", s = "|cFFFFD200PvP:|r Shadowlands: Season 4|nRated Arena and Rated Battleground Season Reward", d = "Trample the Horde to dust while riding a majestic protoform wolf! For the Alliance!" },
    [1466] = { n = "Vicious Warstalker", s = "|cFFFFD200PvP:|r Shadowlands: Season 4|nRated Arena and Rated Battleground Season Reward", d = "Trample the Alliance to dust while riding a majestic protoform wolf! For the Horde!" },
    [1467] = { n = "Noble Bruffalon" },
    [1468] = { n = "Amber Skitterfly" },
    [1469] = { n = "Magmashell", s = "|cFFFFD200Item: |rEmpty Magma Shell|n|cFFFFD200Zone: |rThe Waking Shores", d = "Who's a good little new-forged snail made entirely of elemental lava? You are! Yes, you!" },
    [1470] = { n = "Liquid Hot Magma Slug" },
    [1471] = { n = "Vengeance", s = "|cFFFFD200Drop:|r Lady Sylvanas Windrunner|n|cFFFFD200Zone:|r Sanctum of Domination|n|cFFFFD200Difficulty:|r Mythic", d = "Sylvanas lost a part of herself the day Arthas took her life, and the darkness within her grew to fill the void." },
    [1474] = { n = "Bestowed Thunderspine Packleader" },
    [1475] = { n = "Hand of Bahmethra", s = "|cFFFFD200Drop:|r Tormentors of Torghast|n|cFFFFD200Zone:|r The Maw|n", d = "The most wicked and cruel of her kin, Bahmethra endured the full measure of the Banished One's punishments before her fall." },
    [1476] = { n = "Wild Hunt Legsplitter", s = "|cFFFFD200Drop:|r War Chest of the Wild Hunt|n|cFFFFD200Zone:|r The Maw", d = "Integrated into the depleted forces of the Wild Hunt, the fawn riders quickly found that the gorm's powerful mandibles were perfect for cutting down close enemy ranks." },
    [1477] = { n = "Undying Darkhound", s = "|cFFFFD200Drop:|r War Chest of the Undying Army|n|cFFFFD200Zone:|r The Maw ", d = "The Undying Darkhound's parts have graced many battlefields, yet this latest battle may have been the first time they all fought together." },
    [1478] = { n = "Skyskin Hornstrider" },
    [1480] = { n = "Unchained Gladiator's Soul Eater" },
    [1481] = { n = "Cartel Master's Gearglider", s = "|cFFFFD200Drop:|r So'leah|n|cFFFFD200Zone:|r Tazavesh, the Veiled Market|n", d = "Only the richest cartel leaders are able to afford the metals required to craft the Cartel Master's Gearglider." },
    [1482] = { n = "Xy Trustee's Gearglider" },
    [1483] = { n = "Vandal's Gearglider" },
    [1484] = { n = "Ardenweald Wilderling", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Zone: |rArdenweald", d = "As anima flows to the distant wealds of Ardenweald once more, the wilderlings awaken and cautiously emerge from their canopy burrows." },
    [1485] = { n = "Autumnal Wilderling" },
    [1486] = { n = "Winter Wilderling" },
    [1487] = { n = "Summer Wilderling", s = "|cFFFFD200Covenant: |rNight Fae|n|cFFFFD200Drop:|r Escaped Wilderling|n|cFFFFD200Zone:|r Korthia |n", d = "Stubborn and rebellious, this wilderling is loyal to very few. But those few are bonded for life." },
    [1489] = { n = "Obsidian Gravewing" },
    [1490] = { n = "Sinfall Gravewing", s = "|cFFFFD200Covenant: |rVenthyr|n|cFFFFD200Zone: |rRevendreth", d = "With anima once again flowing in Sinfall, the Stonewright has been able to infuse these Stoneborn, making them valuable allies in the battles to come." },
    [1491] = { n = "Pale Gravewing" },
    [1492] = { n = "Elysian Aquilon", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Zone: |rBastion", d = "With anima once again flowing to the Eternal Forge in Bastion, the plans for the aquilon centurion could be crafted once more." },
    [1493] = { n = "Forsworn Aquilon", s = "|cFFFFD200Covenant: |rKyrian|n|cFFFFD200Drop:|r Wild Worldcracker|n|cFFFFD200Zone:|r Korthia |n", d = "Originally produced by the Forsworn with stolen blueprints, these powerful centurion are now earning a reputation across the Shadowlands." },
    [1494] = { n = "Ascendant's Aquilon" },
    [1495] = { n = "Maldraxxian Corpsefly", s = "|cFFFFD200Covenant: |rNecrolord|n|cFFFFD200Zone: |rMaldraxxus", d = "Corpseflies were once found throughout Maldraxxus, but many died out in the absence of anima. With anima flowing once again, they swarm." },
    [1496] = { n = "Regal Corpsefly" },
    [1497] = { n = "Battlefield Swarmer" },
    [1500] = { n = "Sanctum Gloomcharger", s = "|cFFFFD200Drop:|r The Nine|n|cFFFFD200Zone:|r Sanctum of Domination", d = "Only the Jailer's most powerful lieutenants are gifted these steeds to stalk the halls of the Tower." },
    [1501] = { n = "Soulbound Gloomcharger", s = "|cFFFFD200Drop:|r Mysterious Gift from Ve'nari|n|cFFFFD200Zone:|r The Maw", d = "Ve'nari has many methods of sneaking around the Maw and disrupting the Jailer's plans, including binding his own minions." },
    [3007] = { n = "Blue-Chip Shreddertank" },
    [1502] = { n = "Fallen Charger", s = "|cFFFFD200Drop:|r Fallen Charger|n|cFFFFD200Zone:|r The Maw", d = "The charger's screams echo across the Maw as it continues a never-ending ride across the land, forever looking for escape from the endless torments it has been forced to endure." },
    [1503] = { n = "Hand of Nilganihmaht", s = "|cFFFFD200Zone:|r The Maw", d = "Of all the giants who dared defy the Jailer, Nilganihmaht was the most arrogant. For this transgression, the giant's severed hand was hidden within a veil of torments, and the rings that could summon it back were scattered across the Maw." },
    [1504] = { n = "Hand of Salaranga", s = "|cFFFFD200Achievement:|r Breaking the Chains|n|cFFFFD200Zone:|r Korthia and The Maw", d = "Salaranga was the most cunning of her kin and hid amongst the Beastwarrens. She struck at the Banished One with a horde of bestial allies. It did not matter." },
    [1505] = { n = "Amber Shardhide" },
    [1506] = { n = "Crimson Shardhide", s = "|cFFFFD200Drop:|r Malbog|n|cFFFFD200Zone:|r Korthia", d = "When Korthia was pulled into The Maw, only a few hardy species survived." },
    [1507] = { n = "Darkmaul", s = "|cFFFFD200Zone:|r Korthia", d = "An older shardhide, Darkmaul was relatively tame and friendly around Korthians. He was thought lost to the calamity." },
    [1508] = { n = "Fierce Razorwing", s = "|cFFFFD200Drop:|r Death's Advance Supplies|n|cFFFFD200Zone:|r Korthia", d = "Razorwings generally stay away from other Korthian species, but with time and patience, they can be tamed as well." },
